INSERT INTO public.person (id, name, aliases, era, birth_year, death_year, description, biography, status)
SELECT id, name, aliases, era, birth_year, death_year, description, biography, status FROM jsonb_populate_recordset(NULL::public.person, '[{"name": "李克用", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": 908, "description": "河东晋王，李存勖之父。908年去世，临终命李存勖继承军府。此处的晋不等于后来的后晋。", "biography": "河东晋王，李存勖之父。908年去世，临终命李存勖继承军府。此处的晋不等于后来的后晋。", "status": "draft", "id": "04af206e-fa86-581c-86b9-87a78a8d59a5"}, {"name": "王行瑜", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷256中和四年条所见人物：王行瑜。", "biography": null, "status": "draft", "id": "65e50f4b-8971-5070-b043-77c6748c1fc0"}, {"name": "高爽", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷260乾宁二年条所见人物：高爽。", "biography": null, "status": "draft", "id": "da87001a-9a5a-5dc0-82f8-8653793320f0"}, {"name": "苏文建", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷260乾宁二年条所见人物：苏文建。", "biography": null, "status": "draft", "id": "73af42b3-bb13-5410-be86-9436068bd247"}, {"name": "朱瑄", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷256中和四年条所见人物：朱瑄。", "biography": null, "status": "draft", "id": "dcaf5869-c45e-5845-b02f-6418dd1f22eb"}, {"name": "贺瑰", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷260乾宁二年条所见人物：贺瑰。", "biography": null, "status": "draft", "id": "767516dc-02aa-5314-8b4b-b5be06aaa9bd"}, {"name": "柳存", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷260乾宁二年条所见人物：柳存。", "biography": null, "status": "draft", "id": "2536deef-b038-5da3-9f6e-7a5ec8ad7d72"}, {"name": "何怀宝", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷260乾宁二年条所见人物：何怀宝。", "biography": null, "status": "draft", "id": "ae7df83b-99a0-5326-a682-b2b02b0102a7"}, {"name": "朱温", "aliases": ["朱全忠", "朱晃", "梁太祖"], "era": "五代十国", "birth_year": null, "death_year": 912, "description": "后梁建立者。907年在大梁称帝，912年在宫廷政变中被杀。", "biography": "后梁建立者。907年在大梁称帝，912年在宫廷政变中被杀。", "status": "draft", "id": "0555e455-34d4-54ef-b93e-b0e6425018ab"}, {"name": "朱瑾", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷256中和四年条所见人物：朱瑾。", "biography": null, "status": "draft", "id": "e4226d41-278e-53c7-9e01-7e3572231e8e"}, {"name": "王宗侃", "aliases": ["田师侃"], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷257光启三年条所见人物：王宗侃。", "biography": null, "status": "draft", "id": "75b99890-6c36-5356-ba40-854c4077a4e9"}, {"name": "李继颙", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷260乾宁二年条所见人物：李继颙。", "biography": null, "status": "draft", "id": "348b3985-d2da-5269-9eef-0a42d2dcb07e"}, {"name": "朱琼", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷260乾宁二年条所见人物：朱琼。", "biography": null, "status": "draft", "id": "6a69c33d-47f1-5c1a-8c3a-053000e7d8d8"}, {"name": "董怀进", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷260乾宁二年条所见人物：董怀进。", "biography": null, "status": "draft", "id": "2b157241-0b8c-5a4f-8df2-48bd7186bc92"}, {"name": "朱玭", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷260乾宁二年条所见人物：朱玭。", "biography": null, "status": "draft", "id": "70a56d66-ac40-52a1-b7d1-01e41628708f"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.event (id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status)
SELECT id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status FROM jsonb_populate_recordset(NULL::public.event, '[{"title": "李克用逼邠州，王行瑜哭称无罪请归朝", "start_year": 895, "end_year": 895, "time_original": "895年十一月丁卯前条；确日未载", "dynasty": "唐", "description": "李克用率军逼近邠州。王行瑜登城哭称自己无罪，将胁迫天子归于李茂贞、李继鹏，请李克用移兵凤翔，自愿束身归朝。", "phases": [], "location_name": "邠州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "7c01463f-34b3-5726-ade1-69700f87a97f"}, {"title": "李克用答不能自行决断王行瑜归朝", "start_year": 895, "end_year": 895, "time_original": "895年十一月邠州对答；确日未载", "dynasty": "唐", "description": "李克用答称奉诏讨三贼臣，王行瑜在其中，束身归朝之请非自己能专断。", "phases": [], "location_name": "邠州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "3834f706-8e95-5734-978e-5db1ebcb1743"}, {"title": "王行瑜挈族弃邠州逃走", "start_year": 895, "end_year": 895, "time_original": "895年十一月丁卯", "dynasty": "唐", "description": "王行瑜带家族弃城逃走。", "phases": [], "location_name": "邠州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "1c912867-39e5-5473-8314-10872b33d719"}, {"title": "李克用入邠州封库安抚，命高爽权巡抚", "start_year": 895, "end_year": 895, "time_original": "895年十一月丁卯弃城后条；确日未另载", "dynasty": "唐", "description": "李克用入邠州，封府库、安抚居民，命指挥使高爽暂巡抚军城。", "phases": [], "location_name": "邠州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "c4a3fb86-cf43-5429-a7ac-c78c2c56c1d9"}, {"title": "李克用奏催苏文建赴镇", "start_year": 895, "end_year": 895, "time_original": "895年十一月入邠州后条；确日未载", "dynasty": "唐", "description": "李克用上奏催苏文建赴镇。", "phases": [], "location_name": "朝廷、邠州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "2a114642-3ecd-5063-8d06-8d23d6be32ab"}, {"title": "王行瑜逃至庆州境被部下斩首", "start_year": 895, "end_year": 895, "time_original": "895年十一月逃邠州以后；确日未载", "dynasty": "唐", "description": "王行瑜逃到庆州境内，被部下斩杀并传首。", "phases": [], "location_name": "庆州境", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "bd76a5a3-faab-5b91-a240-9c90265f43b7"}, {"title": "朱瑄遣贺瑰柳存何怀宝袭曹州解兖围", "start_year": 895, "end_year": 895, "time_original": "895年十一月丁卯以前；确日未載", "dynasty": "唐", "description": "朱瑄派其将贺瑰、柳存及河东将何怀宝领一万余人袭曹州，以解兖州围。", "phases": [], "location_name": "曹州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "caf31e89-ca77-5d8d-9c87-720e8ba5062a"}, {"title": "朱温从中都夜追，巨野南败援军", "start_year": 895, "end_year": 895, "time_original": "895年十一月丁卯，夜追至明", "dynasty": "唐", "description": "朱温从中都领兵夜追，天亮到巨野南追及援军，杀伤甚众，擒贺瑰、柳存、何怀宝及三千余士卒。", "phases": [], "location_name": "中都、巨野南", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "f90e6456-ad7c-5d1a-a4f0-bfd1a291e368"}, {"title": "朱温因风沙言杀人未足，下令尽杀俘虏", "start_year": 895, "end_year": 895, "time_original": "895年十一月丁卯晡后", "dynasty": "唐", "description": "当日下午大风沙尘晦冥，朱温说杀人未足，下令将所得俘虏全部杀死。", "phases": [], "location_name": "巨野南战区", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "d3ad2a5e-b7e2-5f71-a16f-68d14dd34230"}, {"title": "朱温缚贺瑰等徇兖州城下劝朱瑾降", "start_year": 895, "end_year": 895, "time_original": "895年十一月庚午", "dynasty": "唐", "description": "朱温将贺瑰等捆缚在兖州城下示众，对朱瑾称其兄已败、劝早降。", "phases": [], "location_name": "兗州城下", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "e7a02223-1353-518d-b647-9246236b4f87"}, {"title": "王宗侃攻克利州，执李继颙斩之", "start_year": 895, "end_year": 895, "time_original": "895年十一月丁丑", "dynasty": "唐", "description": "雅州刺史王宗侃攻克利州，抓获刺史李继颙并将其斩杀。", "phases": [], "location_name": "利州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "f7a89d8f-da14-5a3c-8178-352d5e4e010b"}, {"title": "朱瑾诈降，延寿门与朱温议交符印", "start_year": 895, "end_year": 895, "time_original": "895年十一月辛巳前条；确日未载", "dynasty": "唐", "description": "朱瑾假派使者请降，朱温到延寿门下与其谈话。朱瑾称欲送符印，请朱琼来领。", "phases": [], "location_name": "延寿门", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "17cc2083-b9b4-5f6f-b145-cae3f0b66c94"}, {"title": "朱温遣朱琼，董怀进伏桥下擒之", "start_year": 895, "end_year": 895, "time_original": "895年十一月辛巳", "dynasty": "唐", "description": "朱温派朱琼前往，朱瑾立马桥上，伏勇士董怀进在桥下。朱琼到，董怀进突起，将其擒入城。", "phases": [], "location_name": "兗州桥上、桥下", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "4a1a3216-3d25-5f43-93fa-ac2700d7e98f"}, {"title": "朱琼被斩，首级掷城外", "start_year": 895, "end_year": 895, "time_original": "895年十一月辛巳被擒后须臾", "dynasty": "唐", "description": "朱琼被擒后不久，首级被掷到城外。", "phases": [], "location_name": "兗州城外", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "e7496bae-8f3c-5ced-ab7c-1cb1e3590c7d"}, {"title": "朱温撤军", "start_year": 895, "end_year": 895, "time_original": "895年十一月朱琼被杀后条；确日未载", "dynasty": "唐", "description": "朱温于是率军返回。", "phases": [], "location_name": "兗州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "d23834a9-1527-52c9-ac0a-fa4fccb4828d"}, {"title": "朱温以朱琼弟朱玭为齐州防御使", "start_year": 895, "end_year": 895, "time_original": "895年十一月引兵还条；确日未载", "dynasty": "唐", "description": "朱温以朱琼的弟弟朱玭为齐州防御使。", "phases": [], "location_name": "齐州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "30b97348-9220-5785-8f23-f91d9fbb7f1d"}, {"title": "朱温杀柳存何怀宝", "start_year": 895, "end_year": 895, "time_original": "895年十一月引兵还条；确日未载", "dynasty": "唐", "description": "朱温杀柳存、何怀宝。", "phases": [], "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "原文未给单一地点。", "status": "draft", "id": "8064453b-baba-5efc-b89a-75e9affb0902"}, {"title": "朱温闻贺瑰名，释而用之", "start_year": 895, "end_year": 895, "time_original": "895年十一月处置俘将条；确日未载", "dynasty": "唐", "description": "朱温听闻贺瑰名声，释放并任用他。", "phases": [], "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "原文未给单一地点。", "status": "draft", "id": "b2759c4e-efaf-5da8-8711-082a671fdffa"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

