SELECT id, person_a, person_b, relation_type, description, status FROM jsonb_populate_recordset(NULL::public.person_relationship, '[{"relation_type": "兄长", "description": "朱琼是朱玭的兄长。", "status": "draft", "id": "f4aab8fa-47f2-5d94-a39d-98f6fe55473c", "person_a": "6a69c33d-47f1-5c1a-8c3a-053000e7d8d8", "person_b": "70a56d66-ac40-52a1-b7d1-01e41628708f"}]'::jsonb)
