INSERT INTO public.fact_claim (id, subject_table, subject_id, field_path, claim_text, source_id, citation, note, status)
SELECT id, subject_table, subject_id, field_path, claim_text, source_id, citation, note, status FROM jsonb_populate_recordset(NULL::public.fact_claim, '[{"subject_table": "event", "field_path": "description", "claim_text": "李克用率军逼近邠州。王行瑜登城哭称自己无罪，将胁迫天子归于李茂贞、李继鹏，请李克用移兵凤翔，自愿束身归朝。", "citation": "卷260·乾宁二年（895）·zztj-v260-y0895-p057·原文件第62行", "note": "原文：李克用引兵逼邠州，王行瑜登城，号哭谓克用曰：“行瑜无罪，迫胁乘舆，皆李茂贞及李继鹏所为。请移兵问凤翔，行瑜愿束身归朝。”；核对说明：无罪与归责是行瑜自辩，不由此免责或建立已经归朝结果。", "status": "draft", "id": "1672e7c1-0ef3-5be1-be3b-6e0106557f3c", "subject_id": "7c01463f-34b3-5726-ade1-69700f87a97f", "source_id": "102350a3-9991-5de4-9e22-60443453dfcc"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "895年十一月丁卯前条；确日未载", "citation": "卷260·乾宁二年（895）·zztj-v260-y0895-p057·原文件第62行", "note": "原文：李克用引兵逼邠州，王行瑜登城，号哭谓克用曰：“行瑜无罪，迫胁乘舆，皆李茂贞及李继鹏所为。请移兵问凤翔，行瑜愿束身归朝。”；核对说明：无罪与归责是行瑜自辩，不由此免责或建立已经归朝结果。", "status": "draft", "id": "e8b0a55a-2503-5a8b-b7e6-0cd1fec1baa3", "subject_id": "7c01463f-34b3-5726-ade1-69700f87a97f", "source_id": "102350a3-9991-5de4-9e22-60443453dfcc"}, {"subject_table": "person", "field_path": "description", "claim_text": "本段记李克用：逼城者。", "citation": "卷260·乾宁二年（895）·zztj-v260-y0895-p057·原文件第62行", "note": "原文：李克用引兵逼邠州，王行瑜登城，号哭谓克用曰：“行瑜无罪，迫胁乘舆，皆李茂贞及李继鹏所为。请移兵问凤翔，行瑜愿束身归朝。”克用曰：“王尚父何恭之甚！仆受诏讨三贼臣，公预其一，束身归朝，非仆所得专也。”丁卯，行瑜挈族弃城走。克用入邠州，封府库，抚居人，命指挥使高爽权巡抚军城，奏趣苏文建赴镇。行瑜走至庆州境，部下斩行瑜，传首。；核对说明：按本段原文整理，不补写未载的月日、地点或人物完整生平。", "status": "draft", "id": "e06ae706-43ae-507c-ad22-fee1cc85130e", "subject_id": "04af206e-fa86-581c-86b9-87a78a8d59a5", "source_id": "102350a3-9991-5de4-9e22-60443453dfcc"}, {"subject_table": "person_event", "field_path": "role", "claim_text": "李克用：逼城者。", "citation": "卷260·乾宁二年（895）·zztj-v260-y0895-p057·原文件第62行", "note": "原文：李克用引兵逼邠州，王行瑜登城，号哭谓克用曰：“行瑜无罪，迫胁乘舆，皆李茂贞及李继鹏所为。请移兵问凤翔，行瑜愿束身归朝。”；核对说明：按本段原文整理，不补写未载的月日、地点或人物完整生平。", "status": "draft", "id": "688f8820-873f-589b-80bf-e9a03b427165", "subject_id": "801ad41e-3b97-5e8a-a5f7-60f785dba9fa", "source_id": "102350a3-9991-5de4-9e22-60443453dfcc"}, {